head.script:
scwin.onpageload = function() {
    textbox1.setValue(scwin.$w.id + "bigDecimal_test");
    var t = ""
    if (scwin.$w.id.indexOf("1") >= 0) {
        t = 'scwin.b = scwin.$w.bigDecimal("4");\nscwin.c = scwin.$w.bigDecimal("6");\nscwin.d = scwin.$w.bigDecimal("8")';
    } else {
        t = 'scwin.b = scwin.$w.bigDecimal("5");\nscwin.c = scwin.$w.bigDecimal("7");\nscwin.d = scwin.$w.bigDecimal("9");';
    }
    var str = 'scwin.a = scwin.$w.bigDecimal("3");\n' + t + '\n((scwin.a + scwin.b) * (scwin.c - scwin.d)^scwin.a) / scwin.b")=?';
    textarea1.setValue(str);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function() {
    scwin.a = scwin.$w.bigDecimal("3");
    if (scwin.$w.id.indexOf("1") >= 0) {
        scwin.b = scwin.$w.bigDecimal("4");
    } else {
        scwin.b = scwin.$w.bigDecimal("5");
    }
    if (scwin.$w.id.indexOf("1") >= 0) {
        scwin.c = scwin.$w.bigDecimal("6");
    } else {
        scwin.c = scwin.$w.bigDecimal("7");
    }
    if (scwin.$w.id.indexOf("1") >= 0) {
        scwin.d = scwin.$w.bigDecimal("8");
    } else {
        scwin.d = scwin.$w.bigDecimal("9");
    }
    input1.setValue(scwin.$w.bigDecimal.calc("((scwin.a + scwin.b) * (scwin.c - scwin.d)^scwin.a) / scwin.b"));
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
